cat > /tmp/parse_binlog.cs << 'EOF'
using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;
using System.Collections.Generic;

var build = BinaryLog.ReadBuild(args[0]);
var errors = build.FindChildrenRecursive<Error>();
var warnings = build.FindChildrenRecursive<Warning>();

Console.WriteLine("=== BUILD ERRORS ===");
Console.WriteLine();

// Group errors by project
var errorsByProject = new Dictionary<string, List<Error>>();
foreach (var error in errors)
{
    var project = FindParentProject(error);
    var key = project ?? "(unknown)";
    if (!errorsByProject.ContainsKey(key))
        errorsByProject[key] = new List<Error>();
    errorsByProject[key].Add(error);
}

foreach (var kvp in errorsByProject.OrderBy(k => k.Key))
{
    Console.WriteLine($"Project: {kvp.Key}");
    foreach (var e in kvp.Value)
    {
        Console.WriteLine($"  [{e.Code}] {e.File}({e.LineNumber},{e.ColumnNumber}): {e.Text}");
    }
    Console.WriteLine();
}

Console.WriteLine($"\nTotal errors: {errors.Count()}");
Console.WriteLine($"Total warnings: {warnings.Count()}");

static string? FindParentProject(BaseNode node)
{
    var current = node.Parent;
    while (current != null)
    {
        if (current is Project p)
            return System.IO.Path.GetFileName(p.ProjectFile ?? p.Name);
        current = current.Parent;
    }
    return null;
}
EOF

