cat > /tmp/parse_binlog2.cs << 'EOF'
using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;
using System.Collections.Generic;

var build = BinaryLog.ReadBuild(args[0]);

// Get project dependency info and check for cascading failures
var projects = build.FindChildrenRecursive<Project>();
Console.WriteLine("=== PROJECT BUILD RESULTS ===");
foreach (var p in projects)
{
    var succeeded = p.FindChildrenRecursive<Error>().Count() == 0;
    var deps = p.FindChildrenRecursive<AddItem>()
        .Where(a => a.Name == "ProjectReference")
        .SelectMany(a => a.Children.OfType<Item>())
        .Select(i => System.IO.Path.GetFileName(i.Text))
        .Distinct()
        .ToList();

    Console.WriteLine($"  {System.IO.Path.GetFileName(p.ProjectFile ?? "")} - {(succeeded ? "OK" : "FAILED")}");
    if (deps.Any())
        Console.WriteLine($"    References: {string.Join(", ", deps)}");
}

Console.WriteLine("\n=== SOURCE FILES FROM FAILED PROJECT ===");
// Reconstruct source files from the binlog
var sourceFiles = build.FindChildrenRecursive<SourceFile>();
foreach (var sf in sourceFiles.Where(s => s.SourceFilePath?.Contains("Services") == true))
{
    Console.WriteLine($"  {sf.SourceFilePath}");
}

// Also look at items
Console.WriteLine("\n=== PACKAGE REFERENCES (Services) ===");
foreach (var p in projects.Where(p => p.ProjectFile?.Contains("Services") == true))
{
    var items = p.FindChildrenRecursive<AddItem>()
        .Where(a => a.Name == "PackageReference")
        .SelectMany(a => a.Children.OfType<Item>())
        .Select(i => i.Text)
        .Distinct();
    foreach (var item in items)
        Console.WriteLine($"  {item}");
}

// Check for dependent project failures
Console.WriteLine("\n=== DEPENDENCY ANALYSIS ===");
var failedProjects = new HashSet<string>();
foreach (var p in projects)
{
    if (p.FindChildrenRecursive<Error>().Any())
        failedProjects.Add(System.IO.Path.GetFileName(p.ProjectFile ?? ""));
}

foreach (var p in projects)
{
    var name = System.IO.Path.GetFileName(p.ProjectFile ?? "");
    var deps = p.FindChildrenRecursive<AddItem>()
        .Where(a => a.Name == "ProjectReference")
        .SelectMany(a => a.Children.OfType<Item>())
        .Select(i => System.IO.Path.GetFileName(i.Text))
        .Where(d => failedProjects.Contains(d))
        .Distinct()
        .ToList();

    if (deps.Any())
        Console.WriteLine($"  {name} depends on FAILED project(s): {string.Join(", ", deps)}");
}
EOF

