cd /tmp && cat > parse_binlog.cs << 'EOF'
using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;

var build = BinaryLog.ReadBuild(args[0]);
var projects = build.FindChildrenRecursive<Project>().ToList();

// Check which projects actually failed to build (had build target fail)
Console.WriteLine("=== PROJECT OUTCOMES ===");
foreach (var p in projects)
{
    var name = System.IO.Path.GetFileName(p.ProjectFile ?? "");
    var target = p.FindChildrenRecursive<Target>().FirstOrDefault(t => t.Name == "CoreCompile");
    if (target != null)
    {
        Console.WriteLine($"  {name} (TF={p.TargetFramework}) CoreCompile: Succeeded={target.Succeeded}");
    }
}

// Check if Api project had any build failures due to Services dependency
Console.WriteLine("\n=== Api project messages about dependency failures ===");
foreach (var p in projects.Where(p => p.ProjectFile?.Contains("Api") == true))
{
    var msgs = p.FindChildrenRecursive<Message>()
        .Where(m => m.Text != null && (m.Text.Contains("Services") || m.Text.Contains("failed") || m.Text.Contains("skip")))
        .Take(10)
        .ToList();
    foreach (var m in msgs)
        Console.WriteLine($"  {m.Text}");

    var errs = p.FindChildrenRecursive<Error>().ToList();
    if (errs.Any())
        Console.WriteLine($"  ERRORS: {errs.Count}");
    else
        Console.WriteLine($"  No errors in Api");
}

Console.WriteLine("\n=== Build Result ===");
Console.WriteLine($"  Build succeeded: {build.Succeeded}");
EOF
dotnet run --project parse_binlog.csproj -- /tmp/sv-a2227c09021f420da578266116f9c71b/build.binlog 2>&1 | grep -v "warning NU1603"

